arm.example:
#include <cinux/async.hpp>

using namespace cinux::base;

struct DiskSlot {
    unsigned long last_status = 0;
    unsigned long last_length = 0;
};

void OnDone(DiskSlot& slot, unsigned long status, unsigned long length) {
    slot.last_status = status;
    slot.last_length = length;
}

void Example() {
    DiskSlot slot;
    AsyncCallback<DiskSlot> done;

    done.arm(&OnDone, &slot);
    // done.armed() == true · 回调已经登记，等完成中断来触发
    const bool waiting = done.armed();
    (void)waiting;

    // 同一个回调再登记一次会顶掉旧的，不会叠成两个
    done.arm(&OnDone, &slot);
}

disarm.example:
#include <cinux/async.hpp>

using namespace cinux::base;

struct DiskSlot {
    unsigned long last_status = 0;
};

void OnDone(DiskSlot& slot, unsigned long status, unsigned long length) {
    slot.last_status = status;
    (void)length;
}

void Example() {
    DiskSlot slot;
    AsyncCallback<DiskSlot> done;
    done.arm(&OnDone, &slot);

    done.disarm();
    // done.armed() == false · 登记清掉了，回调不会被触发
    // slot.last_status 仍是 0，因为 OnDone 一次都没跑
    const bool cleared = !done.armed();
    (void)cleared;
}

invoke.example:
#include <cinux/async.hpp>

using namespace cinux::base;

struct DiskSlot {
    unsigned long last_status = 0;
    unsigned long last_length = 0;
    int calls = 0;
};

void OnDone(DiskSlot& slot, unsigned long status, unsigned long length) {
    slot.last_status = status;
    slot.last_length = length;
    ++slot.calls;
}

void Example() {
    DiskSlot slot;
    AsyncCallback<DiskSlot> done;
    done.arm(&OnDone, &slot);

    done.invoke(0, 4096);
    // slot.last_status = 0，slot.last_length = 4096，slot.calls 变成 1
    // done.armed() == false · 触发前先清空登记

    done.invoke(0, 4096);
    // 第二次触发碰到空座，处理器不再跑，slot.calls 还是 1
    const bool empty = !done.armed();
    (void)empty;
}
